Prob033_ece241_2014_q1c.code:
module TopModule (
    input  logic [7:0] a,
    input  logic [7:0] b,
    output logic [7:0] s,
    output logic       overflow
);

    // Perform the 8-bit addition
    assign s = a + b;

    // Overflow detection for signed 2's complement addition:
    // Overflow occurs if the carry into the most significant bit (bit 7)
    // differs from the carry out of the most significant bit.
    // In SystemVerilog, the '+' operator sets the carry flag in the
    // carry bit, but for portable overflow detection we XOR the
    // carry into and out of the MSB.
    // Here we compute it using the internal carry bits.
    // Note: Icarus Verilog simulation may not directly expose the
    // carry prefix operator, so we use a behavioral approach:
    //   - carry_in to MSB:   (a[7] & b[7]) | (a[7] & s[7]) | (b[7] & s[7]) is NOT correct for overflow.
    //   - Correct logic:    overflow = (a[7] == b[7]) && (a[7] != s[7])
    // This captures the case where two positives sum to a negative,
    // or two negatives sum to a positive.

    always_comb begin
        // Default assignment
        overflow = 1'b0;

        // Overflow in signed addition:
        // If both operands are positive (MSB=0) and result is negative (MSB=1)
        // OR both operands are negative (MSB=1) and result is positive (MSB=0)
        if (a[7] == b[7] && a[7] != s[7]) begin
            overflow = 1'b1;
        end
    end

endmodule

Prob086_lfsr5.code:
module TopModule (
    input  logic clk,
    input  logic reset,
    output logic [4:0] q
);

    // Taps at bit positions 5 and 3 (1-indexed from MSB) correspond to
    // indices 4 and 2 (0-indexed from MSB).
    // The LSB (q[0]) is XORed with the tapped bits to produce the
    // new MSB, while all other bits shift right unchanged.
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            q <= 5'b1;      // active-high synchronous reset sets output to 1
        end else begin
            // Compute new MSB: XOR of LSB (q[0]) and the two tapped bits
            logic new_msb;
            new_msb = q[0] ^ q[4] ^ q[2];
            // Shift right: new_msb becomes MSB, others shift down
            q <= {new_msb, q[4:1]};
        end
    end

endmodule

Prob066_edgecapture.code:
`default_nettype none

module TopModule (
    input  wire        clk,
    input  wire        reset,
    input  wire [31:0] in,
    output wire [31:0] out
);

    // Internal register to store the previous value of 'in'
    reg [31:0] prev_in;

    // Internal register to store the captured output
    reg [31:0] captured_out;

    // Combinational logic to detect falling edges (1 -> 0 transition)
    // A falling edge occurs when the current input is 0 and the previous input was 1
    wire [31:0] falling_edge_detect = (~in) & prev_in;

    // Synchronous always block for the positive edge of the clock
    always @(posedge clk) begin
        if (reset) begin
            // Active high synchronous reset: initialize both registers to 0
            prev_in    <= 32'b0;
            captured_out <= 32'b0;
        end else begin
            // Update the previous input register
            prev_in <= in;

            // Update captured output: 
            // If a falling edge is detected, set the corresponding bit in captured_out to 1.
            // Otherwise, retain the current value of captured_out.
            // Note: Once a bit is captured (set to 1), it stays 1 until reset.
            captured_out <= captured_out | falling_edge_detect;
        end
    end

    // Assign the output port
    assign out = captured_out;

endmodule

