    output logic [99:0] out_both,
    output logic [99:0] out_any,
    output logic [99:0] out_different
);

    // out_both: 1 if current bit and its left neighbour are both 1
    // out_both[99] is hardwired to 0 because in[99] has no left neighbour
    assign out_both[99] = 1'b0;
    assign out_both[98:0] = in[98:0] & in[99:1];

    // out_any: 1 if current bit or its right neighbour is 1
    // out_any[0] is hardwired to 0 because in[0] has no right neighbour
    assign out_any[0] = 1'b0;
    assign out_any[99:1] = in[99:1] | in[98:0];

    // out_different: 1 if current bit differs from its left neighbour
    // wraps around: in[99]'s left neighbour is in[0]
    assign out_different = in ^ {in[0], in[99:1]};

