module TopModule(
    input  mode,
    input  too_cold,
    input  too_hot,
    input  fan_on,
    output heater,
    output aircon,
    output fan
);

    // Internal signals to hold the control states for heater and aircon
    // These are registered to avoid glitches in combinational logic
    // but can be driven directly by continuous assignment as well.
    reg heater_reg;
    reg aircon_reg;

    // Combinational logic for heater control
    // In heating mode (mode=1): heater on if too_cold
    // In cooling mode (mode=0): heater off
    always @(*) begin
        if (mode == 1'b1) begin
            heater_reg = too_cold;
        end else begin
            heater_reg = 1'b0;
        end
    end

    // Combinational logic for air conditioner control
    // In cooling mode (mode=0): aircon on if too_hot
    // In heating mode (mode=1): aircon off
    always @(*) begin
        if (mode == 1'b0) begin
            aircon_reg = too_hot;
        end else begin
            aircon_reg = 1'b0;
        end
    end

    // Fan control logic
    // Fan turns on if:
    //   1. Heater is on, OR
    //   2. Air conditioner is on, OR
    //   3. User explicitly requests fan on (fan_on)
    assign fan = heater_reg | aircon_reg | fan_on;

    // Output assignments
    assign heater = heater_reg;
    assign aircon = aircon_reg;

endmodule

