module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Output logic (Moore machine): out is asserted only in state D
    assign out = state[3];  // state[3] is 1 for D, 0 for A, B, C

    // Next state logic derived by inspection with one-hot encoding
    // For each next state bit, we OR the conditions that make that bit high.

    // next_state[0] (bit 0 = A)
    // A is next state when: (current A and in=0) OR (current C and in=0)
    assign next_state[0] = (~state[0] & ~in) | (~state[2] & ~in);

