module TopModule (
    input  clk,
    input  reset,
    input  in,
    output reg done
);

    // State encoding (Moore FSM)
    typedef enum logic [2:0] {
        IDLE       = 3'b000,
        START      = 3'b001,
        DATA       = 3'b010,
        STOP       = 3'b011,
        ERROR      = 3'b100,
        VALID_DATA = 3'b101
    } state_t;

    state_t state, next_state;

    // Bit counter for the 8 data bits (0 = LSB, 7 = MSB)
    logic [3:0] bit_cnt;

    // Sampled data bit (registered input for setup/hold margin)
    logic in_sync;

    // Always block for state transitions and counters
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state       <= IDLE;
            bit_cnt     <= 4'd0;
            done        <= 1'b0;
            in_sync     <= 1'b0;
        end else begin
            state       <= next_state;
            in_sync     <= in;

            case (state)
                IDLE: begin
                    done <= 1'b0;
                    if (in_sync == 1'b0) begin          // Start bit detected (falling edge)
                        next_state <= START;
                        bit_cnt    <= 4'd0;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                START: begin
                    // Wait one clock cycle then sample the first data bit
                    next_state <= DATA;
                    bit_cnt    <= bit_cnt + 4'd1; // bit_cnt = 1
                end

                DATA: begin
                    if (bit_cnt < 4'd8) begin
                        // Shift in data bit (LSB first)
                        bit_cnt <= bit_cnt + 4'd1;
                        if (bit_cnt == 4'd7) begin // Just sampled bit 7 (MSB), next is stop
                            next_state <= STOP;
                        end else begin
                            next_state <= DATA;
                        end
                    end else begin
                        // Should not reach here; handled in STOP transition
                        next_state <= STOP;
                    end
                end

                STOP: begin
                    if (in_sync == 1'b1) begin // Stop bit is 1
                        next_state <= VALID_DATA;
                    end else begin
                        // Stop bit missing – stay in STOP until we see a 1
                        next_state <= STOP;
                    end
                end

                VALID_DATA: begin
                    done <= 1'b1;   // Pulse high for one clock cycle
                    next_state <= IDLE; // Ready for next byte
                end

                ERROR: begin // Should not be entered with current logic, but kept for completeness
                    done <= 1'b0;
                    next_state <= IDLE;
                end

                default: next_state <= IDLE;
            endcase
        end
    end

endmodule

