        C = 2'b10,
        D = 2'b11
    } state_type;

    state_type state, next_state;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            A: begin
                next_state = in ? B : A;
                out        = 1'b0;
            end
            B: begin
                next_state = in ? B : C;
                out        = 1'b0;
            end
            C: begin
                next_state = in ? D : A;
                out        = 1'b0;
            end
            D: begin
                next_state = in ? B : C;
                out        = 1'b1;
            end
            default: begin
                next_state = A;
                out        = 1'b0;
            end
        endcase
    end

    // Flip-flops (positive edge triggered, asynchronous active-high reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= A;
        else
            state <= next_state;
    end

endmodule

