module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);

    // Internal state signal
    reg [1:0] state;

    // Next state logic (combinational)
    wire [1:0] state_next;

    always @(*) begin
        case (state)
            2'b00: begin // Currently walking left
                if (bump_left | bump_right)
                    state_next = 2'b01; // Switch to walking right
                else
                    state_next = 2'b00;
            end
            2'b01: begin // Currently walking right
                if (bump_left | bump_right)
                    state_next = 2'b00; // Switch to walking left
                else
                    state_next = 2'b01;
            end
            default: state_next = 2'b00;
        endcase
    end

    // State update (sequential, positive edge triggered)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b00; // Reset to walk left
        else
            state <= state_next;
    end

    // Output logic (Moore machine: outputs depend only on state)
    // walk_left is 1 when state is 00 (walking left)
    // walk_right is 1 when state is 01 (walking right)
    assign walk_left = (state == 2'b00);
    assign walk_right = (state == 2'b01);

endmodule

