module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);

    // FSM state encoding (2 bits)
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00,
        S_SHIFT1 = 2'b01,
        S_SHIFT2 = 2'b10,
        S_SHIFT3 = 2'b11
    } state_t;

    state_t state, next_state;

    // Sequential logic: state update on positive edge of clk
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= S_IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next-state and output logic (combinational)
    always_comb begin
        // Default assignments
        next_state = state;
        shift_ena  = 1'b0;

        case (state)
            S_IDLE: begin
                // On reset, assert shift_ena for 4 cycles then stay in IDLE
                // But since reset is handled in sequential block, here we just
                // transition to S_SHIFT1 on the first cycle after reset.
                // However, the spec says: "Whenever the FSM is reset, assert
                // shift_ena for 4 cycles, then 0 forever (until reset)."
                // We model this by entering S_SHIFT1 immediately when reset
                // goes high, and cycling through 4 states.
                next_state = S_SHIFT1;
            end

            S_SHIFT1: begin
                shift_ena = 1'b1;
                next_state = S_SHIFT2;
            end

            S_SHIFT2: begin
                shift_ena = 1'b1;
                next_state = S_SHIFT3;
            end

            S_SHIFT3: begin
                shift_ena = 1'b1;
                next_state = S_IDLE;   // After 4 cycles total (S_SHIFT1..S_SHIFT3 + initial)
            end

            default: begin
                next_state = S_IDLE;
            end
        endcase
    end

endmodule

