module TopModule (
    input  clk,
    input  load,
    input  ena,
    input  [1:0] amount,
    input  [63:0] data,
    output reg [63:0] q
);

    always @(posedge clk) begin
        if (load) begin
            // Load the register with the input data
            q <= data;
        end else if (ena) begin
            // Perform shift based on amount
            case (amount)
                2'b00: begin // Shift left by 1 bit
                    q <= q << 1;
                end
                2'b01: begin // Shift left by 8 bits
                    q <= q << 8;
                end
                2'b10: begin // Arithmetic right shift by 1 bit
                    // MSB is replicated to fill the vacated bits
                    q <= { {1{q[63]}}, q[63:1] };
                end
                2'b11: begin // Arithmetic right shift by 8 bits
                    // Fill low 8 bits with MSB
                    q <= { 8{q[63]}, q[63:8] };
                end
                default: q <= q;
            endcase
        end
        // If neither load nor ena, q retains previous value (implicitly)
    end

endmodule

