module TopModule(
    input  [5:0] y,   // one-hot state: y[5:0] = 000001(A) ... 100000(F)
    input        w,
    output       Y1,  // next value for flip-flop y[1]
    output       Y3   // next value for flip-flop y[3]
);

    // State encoding (one-hot):
    // 000001 -> A
    // 000010 -> B
    // 000100 -> C
    // 001000 -> D
    // 010000 -> E
    // 100000 -> F

    // Next-state logic derived by inspection from the FSM:
    // A(000001):   y[1]=0, y[3]=0
    //   w=1 -> B(000010) => y[1]=1, y[3]=0
    //   w=0 -> A(000001) => y[1]=0, y[3]=0
    // B(000010):   y[1]=1, y[3]=0
    //   w=1 -> C(000100) => y[1]=0, y[3]=1
    //   w=0 -> D(001000) => y[1]=0, y[3]=1
    // C(000100):   y[1]=0, y[3]=1
    //   w=1 -> E(010000) => y[1]=1, y[3]=0
    //   w=0 -> D(001000) => y[1]=0, y[3]=1
    // D(001000):   y[1]=0, y[3]=1
    //   w=1 -> F(100000) => y[1]=0, y[3]=1
    //   w=0 -> A(000001) => y[1]=0, y[3]=0
    // E(010000):   y[1]=1, y[3]=0
    //   w=1 -> E(010000) => y[1]=1, y[3]=0
    //   w=0 -> D(001000) => y[1]=0, y[3]=1
    // F(100000):   y[1]=0, y[3]=1
    //   w=1 -> C(000100) => y[1]=0, y[3]=1
    //   w=0 -> D(001000) => y[1]=0, y[3]=1

    // Y1 next value for y[1]:
    // y[1] is set (1) only in states B and E.
    // From B: w=1 -> C (keeps y[1]=0, but we must drive the next state,
    //          actually y[1] becomes 0 in C, so Y1=0 when in B and w=1)
    // Let's re-evaluate directly from the next-state table:
    //  A: w=0->A (y[1]=0), w=1->B (y[1]=1)
    //  B: w=0->D (y[1]=0), w=1->C (y[1]=0)
    //  C: w=0->D (y[1]=0), w=1->E (y[1]=1)
    //  D: w=0->A (y[1]=0), w=1->F (y[1]=0)
    //  E: w=0->D (y[1]=0), w=1->E (y[1]=1)
    //  F: w=0->D (y[1]=0), w=1->C (y[1]=0)
    // Y1 = 1 only when (state==B and w=1) is false? Wait.
    // Let's list Y1 next:
    // A: 0, B: 0, C: 1, D: 0, E: 1, F: 0
    // So Y1 = (state==C) or (state==E)
    // In one-hot: Y1 = (y[2] | y[4])  -- but we must express with the ports available.
    // Since y is 6 bits, we can use the bits directly.
    // y[2] corresponds to state C (000100)
    // y[4] corresponds to state E (010000)
    assign Y1 = y[2] | y[4];

    // Y3 next value for y[3]:
    // y[3] is set (1) only in state D (001000).
    // From the next-state table:
    // A: 0, B: 1, C: 1, D: 1, E: 0, F: 1
    // Wait, let's re-check carefully:
    // A: w=0->A (y[3]=0), w=1->B (y[3]=0) => Y3=0
    // B: w=0->D (y[3]=1), w=1->C (y[3]=1) => Y3=1
    // C: w=0->D (y[3]=1), w=1->E (y[3]=0) => depends on w
    // D: w=0->A (y[3]=0), w=1->F (y[3]=1) => depends on w
    // E: w=0->D (y[3]=1), w=1->E (y[3]=0) => depends on w
    // F: w=0->D (y[3]=1), w=1->C (y[3]=1) => Y3=1
    // Let's derive Y3 as a function of state and w.
    // Y3 = 1 for: (B, any w), (C and w=0), (D and w=1), (E and w=0), (F, any w)
    // Y3 = 0 for: (A, any w), (C and w=1), (D and w=0), (E and w=1)
    // Y3 = (y[1] & ~w) |  // B: y[1]=1, y[3]=1 regardless of w? 
    //      Actually B: y[1]=1, Y3=1. C: y[1]=0, Y3 = ~w.
    //      D: y[1]=0, Y3 = w.
    //      E: y[1]=1, Y3 = ~w.
    //      F: y[1]=0, Y3 = 1.
    // Let's use the minterms derived from the table:
    // Y3 = 1 when:
    //   state B  => y[1] & (~w | w) = y[1]
    //   state C  => ~y[1] & y[2] & ~w
    //   state D  => ~y[1] & y[3] & w   (but y[3] is the current state bit, we are driving next state,
    //          in one-hot transition, we can use current state bits)
    //   state E  => y[1] & ~w
    //   state F  => ~y[1] & ~y[5]  (since F is y[5])
    // This is getting messy. Let's just use the explicit truth table
    // and build the logic with the current state bits y[5:0].
    // Since it's one-hot, exactly one bit of y is 1.
    // We can write a case statement or assign using the bits.
    // Let's list Y3 for each state:
    // A (y[0]): Y3 = 0
    // B (y[1]): Y3 = 1
    // C (y[2]): Y3 = ~w
    // D (y[3]): Y3 = w
    // E (y[4]): Y3 = ~w
    // F (y[5]): Y3 = 1
    // So Y3 = (y[1]) |  // B
    //         (~w & y[2]) |  // C
    //         (w & y[3]) |   // D
    //         (~w & y[4]) |   // E
    //         (~y[0] & ~y[1] & ~y[2] & ~y[3] & ~y[4] & y[5]) // F, but since one-hot, just y[5]
    // However, note that y[5] is F, and in one-hot only one bit is set.
    // So we can write:
    // assign Y3 = y[1] | (~w & y[2]) | (w & y[3]) | (~w & y[4]) | y[5];
    // But wait, y[5] is always 1 when in F, and 0 otherwise. Since one-hot, we can just use y[5].
    // Let's double check the D case: state D, y[3]=1. Y3 = w.
    // If w=1, Y3=1; if w=0, Y3=0. Correct.
    // C case: state C, y[2]=1. Y3 = ~w. If w=1, Y3=0; if w=0, Y3=1. Correct.
    // E case: state E, y[4]=1. Y3 = ~w. Correct.
    // B case: state B, y[1]=1. Y3 = 1. Correct.
    // F case: state F, y[5]=1. Y3 = 1. Correct.
    // A case: state A, all y[5:0]=0. Y3 = 0. Correct.
    // So the assignment is:
    assign Y3 = y[1] | (~w & y[2]) | (w & y[3]) | (~w & y[4]) | y[5];

endmodule

