module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    // State encoding: 2 bits are sufficient (A=00, B=01)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset)
    always_ff @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            A: begin
                // Move to B when s = 1, otherwise stay in A
                if (s)
                    next_state = B;
                // else remain A
            end

            B: begin
                // After examining w for three cycles, transition back to A
                next_state = A;
            end

            default: next_state = A;
        endcase
    end

    // Output logic and cycle counter
    // We need to remember how many clock cycles we have been in state B
    // and whether we have seen exactly two w = 1's in the last three cycles.
    logic [1:0] cycle_cnt;   // 0, 1, 2, 3 (wrapped)
    logic [1:0] ones_cnt;    // count of w=1 in the current window (0..2)

    always_ff @(posedge clk) begin
        if (reset) begin
            cycle_cnt  <= 0;
            ones_cnt   <= 0;
            z          <= 0;
        end else begin
            // Default z is 0
            z <= 0;

            case (state)
                A: begin
                    // Reset counters when leaving state B
                    cycle_cnt <= 0;
                    ones_cnt  <= 0;
                end

                B: begin
                    // Increment cycle counter (max 3)
                    if (cycle_cnt < 3)
                        cycle_cnt <= cycle_cnt + 1;
                    else
                        cycle_cnt <= 0; // wrap around, but we only use up to 3

                    // Update count of w=1's
                    if (w)
                        ones_cnt <= ones_cnt + 1;
                    else
                        ones_cnt <= ones_cnt; // no change

                    // If this is the third cycle (cycle_cnt == 3),
                    // decide the output for the *next* cycle.
                    // Since we are in B on this edge, we look at the count
                    // that includes the current w.
                    // The specification says: "If w = 1 in exactly two of
                    // these clock cycles, then the FSM has to set an output
                    // z to 1 in the following clock cycle."
                    // This means after three cycles of examining w,
                    // the next cycle z becomes 1.
                    // We implement the one-cycle delay by assigning z here,
                    // which will be captured in the next clock edge.
                    if (cycle_cnt == 3 && ones_cnt == 2)
                        z <= 1;
                    else
                        z <= 0;
                end
            endcase
        end
    end

    // Final output z is driven directly in the always_ff block above.
    // No additional assign statement is needed.

endmodule

Prob144_conwaylife.code:
module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [255:0] data,
    output logic [255:0] q
);

// Internal signal for the next state before the clock edge
logic [255:0] next_q;

// Combinational logic: compute the next generation of the Game of Life
always_comb begin
    // Default assignment: next_q follows current q (no change)
    next_q = q;

    // Iterate over every cell in the 16x16 grid
    for (int r = 0; r < 16; r++) begin
        for (int c = 0; c < 16; c++) begin
            // Count the number of live neighbours (toroidal wrapping)
            // Neighbour count fits in 4 bits (max 8)
            logic [3:0] neighbours = 0;

            // Iterate over the 3x3 neighbourhood centred on (r, c)
            for (int dr = -1; dr <= 1; dr++) begin
                for (int dc = -1; dc <= 1; dc++) begin
                    // Skip the cell itself
                    if (dr == 0 && dc == 0) continue;

                    // Compute neighbour coordinates with wrap-around
                    // Modulo operation handles the toroidal wrapping correctly for positive results
                    int nr = (r + dr + 16) % 16;
                    int nc = (c + dc + 16) % 16;

                    // Calculate the linear index of the neighbour
                    // Row 0 occupies bits [15:0], Row 1 occupies [31:16], etc.
                    // Formula: row_index * 16 + column_index
                    int nidx = nr * 16 + nc;

                    // Add to neighbour count if the neighbour is alive
                    neighbours = neighbours + data[nidx];
                end
            end

            // Apply Game of Life rules based on neighbour count
            // Rule (1): 0-1 neighbour -> Cell becomes 0
            // Rule (2): 2 neighbours -> Cell state does not change
            // Rule (3): 3 neighbours -> Cell becomes 1
            // Rule (4): 4+ neighbours -> Cell becomes 0

            if (neighbours <= 1) begin
                next_q[r * 16 + c] = 1'b0;
            end else if (neighbours == 3) begin
                next_q[r * 16 + c] = 1'b1;
            end
            // else (neighbours == 2 or neighbours >= 4) next_q[idx] retains its previous value
            // The default assignment at the top of the block handles the retain case.
        end
    end
end

// Sequential logic: update q on the positive edge of the clock
always_ff @(posedge clk) begin
    if (load) begin
        // Load the initial state from the 'data' input
        q <= data;
    end else begin
        // Otherwise, advance to the next generation
        q <= next_q;
    end
end

endmodule

