module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);

    // State encoding: 0 = waiting for start byte, 1 = received byte 1, 2 = received byte 2, 3 = received byte 3
    typedef enum logic [1:0] {
        STATE_IDLE    = 2'b00,
        STATE_BYTE1   = 2'b01,
        STATE_BYTE2   = 2'b10,
        STATE_BYTE3   = 2'b11
    } state_t;

    state_t state, next_state;

    // State register (synchronous, active high reset)
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= STATE_IDLE;
            done  <= 1'b0;
        end else begin
            state <= next_state;
            done  <= 1'b0; // Clear done each cycle; set only in the cycle after 3rd byte
        end
    end

    // Next-state logic and output generation
    always_comb begin
        next_state = state; // Default: stay in current state

        case (state)
            STATE_IDLE: begin
                // Wait until in[3] is high
                if (in[3]) begin
                    next_state = STATE_BYTE1;
                end else begin
                    next_state = STATE_IDLE;
                end
            end

            STATE_BYTE1: begin
                // Received first byte (with in[3]=1), move to byte 2
                next_state = STATE_BYTE2;
            end

            STATE_BYTE2: begin
                // Received second byte, move to byte 3
                next_state = STATE_BYTE3;
            end

            STATE_BYTE3: begin
                // Received third byte -> signal done in the NEXT cycle
                // (done is cleared at the start of the next clock cycle by the
                //  always_ff block, then set here)
                next_state = STATE_IDLE; // Reset for next message
                // done will be 1 in the cycle after this one due to the
                // non-blocking assignment in the FF block above.
                // However, to make done assert in the cycle immediately after
                // the 3rd byte was received, we must set done here.
                // Since done is cleared at the beginning of the next FF block,
                // we pipeline it: set done in this combinatorial block, and
                // the FF block will capture it on the next edge.
                // But the spec says: "signal the receipt of a message once all
                // 3 bytes have been received (done). The FSM should signal done
                // in the cycle immediately after the third byte of each message
                // was successfully received."
                // 
                // Interpretation: After the 3rd byte is latched (on the clock edge),
                // the next cycle should have done=1.
                // Our FF block clears done at the start of every cycle.
                // Therefore, we must set done in the cycle AFTER STATE_BYTE3.
                // To achieve this, we transition to a temporary state or use
                // the fact that done is cleared then set.
                // Simplest: transition to STATE_IDLE, and set done in the FF
                // block when we detect we just left STATE_BYTE3.
                // However, done is cleared unconditionally at the start of the FF.
                // We need a signal to re-set done in the same cycle it's cleared.
                // 
                // Alternative approach: 
                // Let done be set in the FF block only if the previous state was 
                // STATE_BYTE3. But we don't have a "previous state" register.
                // 
                // Revised plan: 
                // We will add a pulse register or use the transition.
                // Since done is cleared at the beginning of the always_ff block,
                // we can set done in the combinatorial assign block AFTER the FF
                // block? No, always_ff is the only sequential block here.
                // 
                // Let's re-read: "The FSM should signal done in the cycle immediately 
                // after the third byte of each message was successfully received."
                // 
                // If the 3rd byte is received on the rising edge of cycle N,
                // then at the end of cycle N, state becomes STATE_IDLE (or next_state).
                // During cycle N+1, the always_ff block runs. It clears done, 
                // then sets done based on conditions.
                // If we want done=1 in cycle N+1, we need the condition to be true 
                // in the always_ff block for cycle N+1.
                // The condition can be: "if state was STATE_BYTE3 in the previous cycle".
                // But we don't have that.
                // 
                // Workaround: 
                // We can keep a register 'msg_received' that is set when we enter 
                // STATE_BYTE3, and cleared when we leave it. Then done <= msg_received.
                // But the spec says "signal done in the cycle immediately after the 
                // third byte was received".
                // 
                // Let's look at the FF block again:
                // if (reset) ... else begin state <= next_state; done <= 1'b0; end
                // done is always 0 at the start of the cycle.
                // To have done=1 in the cycle after the 3rd byte,
                // we need to set done=1 in that cycle's always_ff block.
                // We can do this by checking if next_state becomes STATE_IDLE 
                // from STATE_BYTE3? No, next_state is computed in comb logic 
                // based on current state.
                // 
                // Actually, we can achieve this by changing the FF block logic:
                // done <= (state == STATE_BYTE3) ? 1'b1 : 1'b0;
                // But wait, if we do that, then in the cycle WHEN we are in STATE_BYTE3,
                // done would be 1. The spec says "immediately after".
                // 
                // Let's trace:
                // Cycle 1: in[3]=1 happens. state transitions to STATE_BYTE1 (next_state).
                //           FF edge: state <= STATE_BYTE1. done <= 0 (because state was IDLE).
                // Cycle 2: state = STATE_BYTE1. next_state = STATE_BYTE2. done <= 0.
                // Cycle 3: state = STATE_BYTE2. next_state = STATE_BYTE3. done <= 0.
                // Cycle 4: state = STATE_BYTE3. next_state = STATE_IDLE. 
                //           FF edge: done <= 1 (if we assign based on state == STATE_BYTE3).
                //           Now, done is 1 in Cycle 4.
                //           But the 3rd byte was received at the end of Cycle 3 (the edge).
                //           "Immediately after the third byte... was received" -> Cycle 4.
                //           This matches!
                // 
                // Let's verify the "discard bytes until we see one with in[3]=1" part.
                // Cycle 1: Reset. in[3]=0. state=IDLE. done=0.
                // Cycle 2: in[3]=0. state=IDLE. done=0.
                // Cycle 3: in[3]=1. next_state=BYTE1. FF: state <= BYTE1. done <= 0 (state was IDLE).
                // Cycle 4: state=BYTE1. next_state=BYTE2. done <= 0.
                // Cycle 5: state=BYTE2. next_state=BYTE3. done <= 0.
                // Cycle 6: state=BYTE3. next_state=IDLE. FF: done <= 1.
                // Cycle 7: state=IDLE. done <= 0 (cleared at start of FF block).
                // 
                // This seems correct.
                // 
                // However, there is a catch.
                // The always_ff block: "done <= 1'b0; ... done <= ..."?
                // If I write:
                //   always_ff @(posedge clk) begin
                //       if (reset) ...
                //       else begin
                //           state <= next_state;
                //           done <= (state == STATE_BYTE3) ? 1'b1 : 1'b0;
                //       end
                //   end
                // 
                // In Cycle 4 (state=BYTE3):
                //   The RHS of done <= is evaluated. state is BYTE3.
                //   So done <= 1.
                //   This 1 is scheduled for the FF output at the posedge.
                //   At the posedge, state becomes next_state (IDLE).
                //   done becomes 1.
                //   This is the cycle AFTER the 3rd byte was latched (which was the posedge of Cycle 3).
                //   So done=1 in Cycle 4. Correct.
                // 
                // What about the clearing?
                // The expression (state == STATE_BYTE3) ? 1'b1 : 1'b0 will be 0 in all other cycles.
                // So done is effectively 0 when not in STATE_BYTE3.
                // This satisfies "done should be signalled... once all 3 bytes have been received 
                // (done). The FSM should signal done in the cycle immediately after the third byte...".
                // 
                // Wait, let's re-read the FF block I initially wrote:
                // "done <= 1'b0; // Clear done each cycle; set only in the cycle after 3rd byte"
                // If I write done <= 1'b0; unconditionally, then I cannot set it to 1 later in the same block
                // unless I use an if-else.
                // If I structure it as:
                //   always_ff @(posedge clk) begin
                //       if (reset) begin state <= ...; done <= 0; end
                //       else begin
                //           state <= next_state;
                //           if (state == STATE_BYTE3) done <= 1'b1;
                //           else        done <= 1'b0;
                //       end
                //   end
                // This works perfectly.
                // 
                // Let's refine the STATE_BYTE3 case in comb logic.
                // next_state = STATE_IDLE; // Always go back to idle after 3rd byte
                // We don't necessarily need to do anything special in the comb logic for STATE_BYTE3
                // regarding next_state, other than going back to IDLE.
                // The done signaling is handled entirely in the FF block based on the current state.
                // 
                // Let's double check the "discard" logic.
                // In STATE_IDLE, if in[3] is 1, we go to STATE_BYTE1.
                // This effectively discards all previous bytes.
                // 
                // One edge case: What if a byte with in[3]=1 appears, we start counting,
                // and then the next two bytes also have in[3]=1? 
                // The spec says: "in[3] of the other two bytes may be 1 or 0 depending on data".
                // Our FSM just counts three bytes regardless of in[3] value in state BYTE2 and BYTE3.
                // This matches the spec.
                // 
                // Let's write the code.

            end
        endcase
    end

    // Simplified next_state assignment based on the case above.
    // I will restructure the always_comb to be cleaner.

    always_comb begin
        next_state = state; // Default

        case (state)
            STATE_IDLE: begin
                if (in[3])
                    next_state = STATE_BYTE1;
                // else stay IDLE (default)
            end
            STATE_BYTE1: next_state = STATE_BYTE2;
            STATE_BYTE2: next_state = STATE_BYTE3;
            STATE_BYTE3: next_state = STATE_IDLE; // Reset state for next message
        endcase
    end

    // State register and done signaling
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= STATE_IDLE;
            done    <= 1'b0;
        end else begin
            state <= next_state;
            // Logic for done:
            // The spec requires done to be 1 in the cycle immediately after the 3rd byte was received.
            // The 3rd byte is received when the state transitions INTO STATE_BYTE3 
            // (or is currently in STATE_BYTE3 having just been latched).
            // If we are in STATE_BYTE3 now, it means the 3rd byte was received in the previous cycle.
            // Therefore, done should be 1 now.
            if (state == STATE_BYTE3)
                done <= 1'b1;
            else
                done <= 1'b0;
        end
    end

endmodule

Prob153_gshare.code:
module TopModule (
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

    // 7-bit global branch history register
    reg [6:0] ghr;

    // 128-entry PHT (2-bit saturating counters)
    // Index is computed as (pc XOR ghr)[6:0]
    reg [1:0] pht [0:127];

    // Internal signals for prediction path
    wire [6:0] idx;
    wire [1:0] pht_val;
    wire taken_internal;

    // Index computation: XOR of pc and ghr
    assign idx = predict_pc ^ ghr;

    // PHT read (combinational)
    assign pht_val = pht[idx];

    // Two-bit saturating counter logic
    // taken if counter >= 2'b10
    assign taken_internal = (pht_val >= 2'b10);

    // Prediction output
    assign predict_taken = taken_internal;
    assign predict_history = ghr;

    // Training logic
    // When train_valid is asserted, update PHT and optionally GHR
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
            // Initialize PHT to weakly taken (2'b01) or any initial state
            // Here we reset to 2'b00 for simplicity
            integer i;
            for (i = 0; i < 128; i = i + 1) begin
                pht[i] <= 2'b00;
            end
        end else begin
            if (train_valid) begin
                // Compute training index
                // For training, the spec says "told the pc and branch history register value"
                // We use train_pc XOR train_history for the index
                // However, the GHR state used for training index might be the current GHR
                // or the state at the time of the branch. 
                // The spec says: "if the branch being trained is mispredicted, also recover the 
                // branch history register to the state immediately after the mispredicting branch 
                // completes execution."
                // We interpret this as updating GHR based on actual outcome.

                // Update PHT
                // Standard gshare training: if taken, increment; if not taken, decrement
                if (train_taken) begin
                    if (pht[train_pc ^ train_history] < 2'b11)
                        pht[train_pc ^ train_history] <= pht[train_pc ^ train_history] + 1;
                end else begin
                    if (pht[train_pc ^ train_history] > 2'b00)
                        pht[train_pc ^ train_history] <= pht[train_pc ^ train_history] - 1;
                end

                // Update GHR if mispredicted: recover to state after mispredicting branch
                // The spec says: "if the branch being trained is mispredicted, also recover the 
                // branch history register to the state immediately after the mispredicting branch 
                // completes execution."
                // This implies shifting in the actual outcome.
                if (train_mispredicted) begin
                    // Recover GHR: shift in the actual taken value
                    // Typically: ghr <= (ghr << 1) | train_taken;
                    // But "recover to state after mispredicting branch" might mean 
                    // the GHR content at the point of misprediction.
                    // We will shift in the actual outcome.
                    ghr <= (ghr << 1) | train_taken;
                end
            end else begin
                // No training, update GHR on prediction
                if (predict_valid) begin
                    // Prediction updates GHR with predicted taken value
                    // "The branch history register is then updated (at the next positive clock edge) 
                    // for the predicted branch."
                    ghr <= (ghr << 1) | taken_internal;
                end
            end
        end
    end

endmodule

Prob151_review2015_fsm.code:
module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

// State encoding: 3 bits sufficient for the described states
typedef enum logic [2:0] {
    S_IDLE      = 3'b000,  // Searching for the start pattern 1101
    S_SHIFT     = 3'b001,  // Shift in 4 bits to determine duration
    S_COUNTING  = 3'b010,  // Waiting for counters to finish
    S_DONE      = 3'b011   // Timer timed out, waiting for ack
} state_t;

state_t state, next_state;

// Shift register to detect the pattern 1101
// We keep the last 4 bits of the serial stream
logic [3:0] shift_reg;

// Detect rising edge of the pattern 1101
// Pattern detected when shift_reg == 4'b1101
always_ff @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
    end else begin
        // Shift in the new data bit
        shift_reg <= {shift_reg[2:0], data};
    end
end

// State transition logic
always_ff @(posedge clk) begin
    if (reset) begin
        state <= S_IDLE;
    end else begin
        state <= next_state;
    end
end

// Next-state and output logic (combinational)
always_comb begin
    // Default assignments: keep outputs unchanged unless transitioning
    next_state = state;
    shift_ena  = 1'b0;
    counting   = 1'b0;
    done       = 1'b0;

    case (state)
        S_IDLE: begin
            // Look for the pattern 1101
            if (shift_reg == 4'b1101) begin
                next_state = S_SHIFT;
            end else begin
                next_state = S_IDLE;
            end
        end

        S_SHIFT: begin
            // Assert shift_ena for exactly 4 clock cycles
            shift_ena = 1'b1;

            // We use a 2-bit counter (shift_cnt) internally to track the 4 cycles.
            // The counter counts 0 -> 1 -> 2 -> 3. 
            // When it reaches 3, the next clock cycle will transition to S_COUNTING.
            // However, since we are in the combinational block, we determine the 
            // next state based on the counter value held in the flip-flop.
            // To simplify: we transition to S_COUNTING when shift_cnt equals 3'b11 (3).
            // Note: The shift_cnt update happens in the sequential block.

            if (shift_cnt == 2'b11)
                next_state = S_COUNTING;
            else
                next_state = S_SHIFT;
        end

        S_COUNTING: begin
            counting = 1'b1;
            if (done_counting) begin
                next_state = S_DONE;
            end else begin
                next_state = S_COUNTING;
            end
        end

        S_DONE: begin
            done = 1'b1;
            if (ack) begin
                next_state = S_IDLE;
            end else begin
                next_state = S_DONE;
            end
        end
    endcase
end

// Counter for shift_ena duration (2 bits: 0, 1, 2, 3)
// This counter tracks how many cycles we have spent in S_SHIFT.
logic [1:0] shift_cnt;

always_ff @(posedge clk) begin
    if (reset) begin
        shift_cnt <= 2'b00;
    end else begin
        case (state)
            S_SHIFT: begin
                // Increment counter if not already at 3
                if (shift_cnt < 3)
                    shift_cnt <= shift_cnt + 1'b1;
                else
                    shift_cnt <= shift_cnt; // Hold at 3
            end
            default: begin
                // Reset counter when leaving S_SHIFT (e.g., to S_COUNTING or S_IDLE)
                shift_cnt <= 2'b00;
            end
        endcase
    end
end

endmodule

