module TopModule(
    input clk,
    input areset,
    input x,
    output z
);

    reg [7:0] state;
    reg [7:0] count;
    reg signed [8:0] value;
    assign z = value[8];

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= 0;
            count <= 0;
            value <= 0;
        end else begin
            if (state == 0) begin
                count <= 0;
                value <= 0;
                state <= 1;
            end else if (state == 1) begin
                value[0] <= ~x;
                count <= count + 1;
                if (count == 8) begin
                    state <= 2;
                end
            end else if (state == 2) begin
                value <= value >> 1;
                value[8] <= ~value[0];
                if (count == 0) begin
                    state <= 0;
                end else begin
                    count <= count - 1;
                end
            end
        end
    end

endmodule

